#!/usr/bin/env python3
from __future__ import annotations

import base64
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PARTS = [
    ROOT / "scripts/.biomateriales_implantes_u3_payload_01.txt",
    ROOT / "scripts/.biomateriales_implantes_u3_payload_02.txt",
    ROOT / "scripts/.biomateriales_implantes_u3_payload_03.txt",
]
TEST_PAYLOAD = ""

payload = "".join(path.read_text(encoding="utf-8").strip() for path in PARTS)
unit_bytes = zlib.decompress(base64.b64decode(payload))
test_bytes = zlib.decompress(base64.b64decode(TEST_PAYLOAD))

source = ROOT / "data/course_redevelopment/biomateriales-implantes/units/unit-03.json"
mirror = ROOT / "data/generated_units/biomateriales-implantes/unit-03.json"
test = ROOT / "tests/test_biomateriales_implantes_unit_03_curated.py"
source.write_bytes(unit_bytes)
mirror.write_bytes(unit_bytes)
test.write_bytes(test_bytes)

if source.read_bytes() != mirror.read_bytes():
    raise SystemExit("source/generated mirror mismatch")
if b"Concepto de la unidad que debe definirse mediante entidades observables" in unit_bytes:
    raise SystemExit("generic marker remains")
print("Biomateriales e Implantes U3 curated deterministically.")
